ALTER TABLE cliente ADD COLUMN holded_contact_id VARCHAR(100) NULL, ADD COLUMN modalidad_facturacion_predeterminada VARCHAR(30) NOT NULL DEFAULT 'POR_EXPEDIENTE', ADD COLUMN tipo_via VARCHAR(30) NULL, ADD COLUMN nombre_via VARCHAR(120) NULL, ADD COLUMN numero_via VARCHAR(20) NULL, ADD COLUMN bloque VARCHAR(20) NULL, ADD COLUMN portal VARCHAR(20) NULL, ADD COLUMN escalera VARCHAR(20) NULL, ADD COLUMN piso VARCHAR(20) NULL, ADD COLUMN puerta VARCHAR(20) NULL, ADD COLUMN codigo_postal VARCHAR(10) NULL, ADD COLUMN municipio VARCHAR(80) NULL, ADD COLUMN localidad VARCHAR(120) NULL, ADD COLUMN provincia VARCHAR(80) NULL, ADD CONSTRAINT uk_cliente_holded_contact UNIQUE (holded_contact_id);
ALTER TABLE interesado ADD COLUMN localidad VARCHAR(120) NULL;
ALTER TABLE solicitud ADD COLUMN interesado1_localidad VARCHAR(255) NULL, ADD COLUMN interesado2_localidad VARCHAR(255) NULL, ADD COLUMN interesado3_localidad VARCHAR(255) NULL;
ALTER TABLE aviso_incidencia MODIFY COLUMN enviado_por_usuario_id BIGINT NULL;
CREATE TABLE factura_holded (id BIGINT NOT NULL AUTO_INCREMENT, holded_invoice_id VARCHAR(100) NOT NULL, holded_contact_id VARCHAR(100) NULL, cliente_id BIGINT NULL, numero VARCHAR(80) NULL, contacto_nombre VARCHAR(180) NULL, contacto_nif VARCHAR(30) NULL, fecha_emision DATE NULL, fecha_vencimiento DATE NULL, total DECIMAL(14,2) NULL, importe_pagado DECIMAL(14,2) NULL, moneda VARCHAR(3) NULL, estado VARCHAR(30) NOT NULL, actualizada_holded DATETIME(6) NULL, sincronizada_en DATETIME(6) NOT NULL, modalidad_facturacion VARCHAR(30) NULL, periodo_desde DATE NULL, periodo_hasta DATE NULL, archivo_factura VARCHAR(180) NULL, archivo_factura_original VARCHAR(255) NULL, archivo_factura_content_type VARCHAR(100) NULL, archivo_factura_tamano BIGINT NULL, PRIMARY KEY (id), CONSTRAINT uk_factura_holded_invoice UNIQUE (holded_invoice_id), CONSTRAINT fk_factura_holded_cliente FOREIGN KEY (cliente_id) REFERENCES cliente (id), INDEX idx_factura_holded_cliente_fecha (cliente_id, fecha_emision), INDEX idx_factura_holded_contacto (holded_contact_id));
CREATE TABLE factura_expediente (id BIGINT NOT NULL AUTO_INCREMENT, factura_id BIGINT NOT NULL, expediente_id BIGINT NOT NULL, estado VARCHAR(30) NOT NULL, matricula_detectada VARCHAR(15) NULL, bastidor_detectado VARCHAR(40) NULL, comprador_identificador_detectado VARCHAR(30) NULL, confianza INT NOT NULL, motivo_revision VARCHAR(500) NULL, creado_en DATETIME(6) NOT NULL, confirmado_en DATETIME(6) NULL, PRIMARY KEY (id), CONSTRAINT uk_factura_expediente_expediente UNIQUE (expediente_id), CONSTRAINT fk_factura_expediente_factura FOREIGN KEY (factura_id) REFERENCES factura_holded (id), CONSTRAINT fk_factura_expediente_expediente FOREIGN KEY (expediente_id) REFERENCES expediente (id), INDEX idx_factura_expediente_factura (factura_id, estado));
CREATE TABLE comprobante_pago (id BIGINT NOT NULL AUTO_INCREMENT, factura_id BIGINT NOT NULL, aportado_por_usuario_id BIGINT NOT NULL, nombre_archivo VARCHAR(500) NOT NULL, nombre_original VARCHAR(255) NOT NULL, content_type VARCHAR(100) NOT NULL, tamano BIGINT NOT NULL, estado VARCHAR(30) NOT NULL, observaciones VARCHAR(500) NULL, creado_en DATETIME(6) NOT NULL, revisado_en DATETIME(6) NULL, PRIMARY KEY (id), CONSTRAINT fk_comprobante_factura FOREIGN KEY (factura_id) REFERENCES factura_holded (id), CONSTRAINT fk_comprobante_usuario FOREIGN KEY (aportado_por_usuario_id) REFERENCES usuario (id), INDEX idx_comprobante_factura_estado (factura_id, estado));
CREATE TABLE holded_webhook_evento (id BIGINT NOT NULL AUTO_INCREMENT, event_id VARCHAR(150) NOT NULL, recibido_en DATETIME(6) NOT NULL, procesado BIT NOT NULL, PRIMARY KEY (id), CONSTRAINT uk_holded_webhook_evento UNIQUE (event_id));
CREATE TABLE justificante_provisional (id BIGINT NOT NULL AUTO_INCREMENT, solicitud_id BIGINT NOT NULL, estado VARCHAR(30) NOT NULL, nombre_archivo VARCHAR(500) NULL, nombre_original VARCHAR(255) NULL, solicitado_en DATETIME(6) NULL, actualizado_en DATETIME(6) NOT NULL, PRIMARY KEY (id), CONSTRAINT uk_justificante_solicitud UNIQUE (solicitud_id), CONSTRAINT fk_justificante_solicitud FOREIGN KEY (solicitud_id) REFERENCES solicitud (id));